{{ config(materialized='table', schema='ENVIRONMENT') }}

-- Source: NOAA NCEI Storm Events Database (bulk CSV) (69801 rows)
-- Generated by gen_mart_models.py

with source as (
    select * from {{ source('ripple_raw', 'FED_NOAA_STORM_EVENTS') }}
)

select
    BEGIN_YEARMONTH as begin_yearmonth,
    BEGIN_DAY as begin_day,
    BEGIN_TIME as begin_time,
    END_YEARMONTH as end_yearmonth,
    END_DAY as end_day,
    END_TIME as end_time,
    EPISODE_ID as episode_id,
    EVENT_ID as event_id,
    STATE as state,
    STATE_FIPS as state_fips,
    try_to_number("YEAR") as year,
    MONTH_NAME as month_name,
    EVENT_TYPE as event_type,
    CZ_TYPE as cz_type,
    CZ_FIPS as cz_fips,
    CZ_NAME as cz_name,
    WFO as wfo,
    try_to_timestamp(BEGIN_DATE_TIME) as begin_date_time,
    CZ_TIMEZONE as cz_timezone,
    try_to_timestamp(END_DATE_TIME) as end_date_time,
    INJURIES_DIRECT as injuries_direct,
    INJURIES_INDIRECT as injuries_indirect,
    try_to_number(DEATHS_DIRECT) as deaths_direct,
    try_to_number(DEATHS_INDIRECT) as deaths_indirect,
    DAMAGE_PROPERTY as damage_property,
    DAMAGE_CROPS as damage_crops,
    SOURCE as source,
    MAGNITUDE as magnitude,
    MAGNITUDE_TYPE as magnitude_type,
    FLOOD_CAUSE as flood_cause,
    CATEGORY as category,
    TOR_F_SCALE as tor_f_scale,
    TOR_LENGTH as tor_length,
    TOR_WIDTH as tor_width,
    TOR_OTHER_WFO as tor_other_wfo,
    TOR_OTHER_CZ_STATE as tor_other_cz_state,
    TOR_OTHER_CZ_FIPS as tor_other_cz_fips,
    TOR_OTHER_CZ_NAME as tor_other_cz_name,
    BEGIN_RANGE as begin_range,
    BEGIN_AZIMUTH as begin_azimuth,
    BEGIN_LOCATION as begin_location,
    END_RANGE as end_range,
    END_AZIMUTH as end_azimuth,
    END_LOCATION as end_location,
    try_to_double(BEGIN_LAT) as begin_lat,
    try_to_double(BEGIN_LON) as begin_lon,
    try_to_double(END_LAT) as end_lat,
    try_to_double(END_LON) as end_lon,
    EPISODE_NARRATIVE as episode_narrative,
    EVENT_NARRATIVE as event_narrative,
    DATA_SOURCE as data_source
from source
